using System.Buffers.Binary;
using System.Collections.Immutable;
using System.IO.Compression;
using System.Reflection;
using System.Text.Json;
using System.Xml.Linq;
using Aion.Commons.Nio;
using Aion.GameServer.GeoEngine.RetailPath;
using Aion.GameServer.Network.Aion;
using C=Aion.GameServer.Controllers.Attack.RetailNpc.RetailNpcUserStatSourceCatalog;
using P=Aion.GameServer.GeoEngine.RetailPath.RetailNpc48PresentationInputs;
using Q=Aion.GameServer.GeoEngine.RetailPath.RetailNpc48CompletedPackets;
using O=Aion.GameServer.GeoEngine.RetailPath.RetailNpcManagedMembershipObservation;
using M=Aion.GameServer.GeoEngine.RetailPath.RetailNpcManagedMembershipMove;

namespace Aion.GameServer.Tests;

public sealed class RetailNpc48PresentationInputsTests
{
    [Fact] public void CompleteOriginalSourceOwnsAll25RecordsAndPreserves21AiOnlyDifferences()
    {
        var s=Spawn48Fixture.Sources;Assert.Equal(25,s.SelectedNpcIds.Length);Assert.Equal(21,s.AiDifferences.Length);
        Assert.Equal(6,s.CurrentXmlZoneNames.Count);Assert.Equal(P.BundleSha256,s.SnapshotSha256);
        Assert.False(s.LoadedRegistryObserved);Assert.False(s.ActivationReady);
        Assert.DoesNotContain(typeof(P.Sources).GetConstructors(BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic),x=>!x.IsPrivate);
        Assert.DoesNotContain(typeof(P.Capability).GetConstructors(BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic),x=>!x.IsPrivate);
    }
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]
    public void MissingDuplicateChangedAndDefaultSourceBytesCannotBeAdmitted(int kind)
    {
        var files=Spawn48Fixture.SourceFiles;
        files=kind switch{0=>files.RemoveAt(0),1=>files.SetItem(1,files[0]),2=>files.SetItem(0,files[0] with{Bytes=files[0].Bytes.SetItem(0,(byte)(files[0].Bytes[0]^1))}),_=>default};
        Assert.Throws<P.Fault>(()=>P.Sources.Admit(files));
    }
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]
    public void ContextPolicyProgramsAndCollectionUnknownsRejectBeforePublication(int kind)
    {
        var f=new Spawn48Fixture();var raw=f.Raw;
        raw=kind switch{0=>raw with{Evidence=raw.Evidence with{Policy="another"}},1=>raw with{Evidence=raw.Evidence with{Origin=P.Origin.Unknown}},
            2=>raw with{Evidence=raw.Evidence with{ProgramsSha256=new string('a',64)}},3=>raw with{Players=default},_=>raw with{OriginalBirthClocks=default}};
        Assert.Throws<P.Fault>(()=>P.Capability.Admit(Spawn48Fixture.Sources,raw));
    }
    [Fact] public void CapabilityHashIncludesPrivateItemSourceIdentityAndDefaultMarkers()
    {
        var f=new Spawn48Fixture();var a=f.Capability();var b=P.Capability.Admit(Spawn48Fixture.Sources,f.Raw with{Npc=f.Raw.Npc with{OriginalMasterNameField=new(true,"another")}});
        Assert.NotEqual(a.SnapshotSha256,b.SnapshotSha256);Assert.False(a.CurrentHostObserved);Assert.False(a.ActivationReady);
        var untouched=f.Raw.OriginalBirthClocks;f.Raw=f.Raw with{OriginalBirthClocks=f.Raw.OriginalBirthClocks.SetItem(0,f.Raw.OriginalBirthClocks[0] with{UnixMillis=1})};
        Assert.Equal(untouched.ToArray(),a.Original.OriginalBirthClocks.ToArray());Assert.NotEqual(a.SnapshotSha256,f.Capability().SnapshotSha256);
    }
    [Fact] public void DifferentUnpairedUtf16UnitsHaveDifferentPresentationHashes()
    {
        var f=new Spawn48Fixture();f.Raw=f.Raw with{Npc=f.Raw.Npc with{OriginalMasterNameField=new(true,"A\ud800B")}};var a=f.Capability();
        f.Raw=f.Raw with{Npc=f.Raw.Npc with{OriginalMasterNameField=new(true,"A\ud801B")}};Assert.NotEqual(a.SnapshotSha256,f.Capability().SnapshotSha256);
    }
    [Theory][InlineData(0)][InlineData(1)]
    public void DuplicatePhysicalPlayersAndTargetsAreNotSeparateOwners(int kind)
    {
        var f=new Spawn48Fixture();var raw=kind==0?f.Raw with{Players=f.Raw.Players.Add(f.Raw.Players[0])}:
            f.Raw with{OriginalTargetObjects=[new(101,"user-life-1",Q.PlayerRuntime,"world","world-generation",P.MapId,1,false),new(101,"other",Q.PlayerRuntime,"world","world-generation",P.MapId,1,false)]};
        Assert.Throws<P.Fault>(()=>P.Capability.Admit(Spawn48Fixture.Sources,raw));
    }
    [Fact] public void CurrentSourceRootsAreSixAndNoJavaWorldZoneIsInvented()
    {
        var f=new Spawn48Fixture();Assert.Equal(6,f.Raw.World.OriginalCompleteRegistrations.Length);
        Assert.All(f.Raw.World.OriginalCompleteRegistrations,x=>Assert.Equal(P.ZoneProducer.XmlZoneTemplate,x.Producer));
        Assert.DoesNotContain(f.Raw.World.OriginalCompleteRegistrations,x=>x.OriginalName==P.MapId.ToString());
        Assert.All(Spawn48Fixture.Sources.SelectedNpcIds,id=>Assert.NotEmpty(Spawn48Fixture.Sources.Npc(id).CurrentRawSha256));
    }
}

internal sealed class Spawn48Fixture
{
    internal static readonly JsonDocument SourceJson=Unzip(SourcePayload);
    internal static readonly JsonDocument Cases=Unzip(CasePayload);
    internal static readonly ImmutableArray<P.SourceFile> SourceFiles=[..SourceJson.RootElement.GetProperty("files").EnumerateArray()
        .Select(x=>new P.SourceFile(x.GetProperty("name").GetString()!,[..Convert.FromBase64String(x.GetProperty("base64").GetString()!)]))];
    internal static readonly P.Sources Sources=P.Sources.Admit(SourceFiles);
    internal O.Input Input;
    internal P.Raw Raw;
    internal Q.Limits Limits=new(32,100000,10000);
    internal Spawn48Fixture(uint npc=212776,string race="ELYOS",float oldX=31,float newX=32)
    {
        Input=ManagedMembershipFixture.Make(oldX,newX);
        Input=ManagedMembershipFixture.NpcImage(Input,image=>
        {
            var raw=image.Bytes.ToArray();ManagedMembershipFixture.W32(raw,0x100,npc);
            raw.AsSpan(0x1440,2).Clear(); // Known first terminator; later bytes/stat fields are unchanged.
            BinaryPrimitives.WriteUInt16LittleEndian(raw.AsSpan(0x14a8,2),2300);
            BinaryPrimitives.WriteUInt16LittleEndian(raw.AsSpan(0x14a6,2),777);
            return image with{Bytes=[..raw]};
        });
        P.Binding Bind(uint id,string life)=>new(id,life,"world","world-generation",P.MapId,1,Sources.SnapshotSha256);
        var users=Input.Scene.Users.Select(u=>new P.Player(Bind(u.Key.ObjectId,u.Key.Lifetime),Q.PlayerRuntime,race,0,P.Reference.Null,P.Reference.Null)).ToImmutableArray();
        var zones=Sources.CurrentXmlZoneNames.Order(StringComparer.Ordinal).Select((name,i)=>new P.ZoneRegistration("xml-zone-"+i,"zone-generation-"+i,
            P.ZoneProducer.XmlZoneTemplate,Q.XmlZoneRuntime,name,P.MapId,Sources.SnapshotSha256,"zone-generation-"+i,0,null,null)).ToImmutableArray();
        Raw=new(new(P.Origin.ConstructedSourceFixture,P.Policy,O.PackageContext,P.CurrentProgramsSha256,Input.Evidence.Operation,Input.Evidence.Epoch,"constructed original fields, not live capture"),
            new(Bind(7,"npc-life"),Q.NpcRuntime,(int)npc,0x1234,0x56,0,new(true,""),P.Reference.Null,new(P.Reference.Null,null),90000,true,
                new(P.EquipmentKind.NoOverride,"not-reached","not-reached","not-reached",[]),new(P.SpawnKind.OrdinarySpawnTemplate,"spawn7","spawn-generation",Q.SpawnRuntime,70000)),
            users,[],new("world","world-generation",P.MapId,1,"ZoneService.CreateZoneInstances","zone-registry-generation",Sources.SnapshotSha256,zones),
            [new(100,"user-life-0","connection-0",7,"npc-life",100000,Input.Evidence.Operation,Input.Evidence.Epoch,"constructed original host Unix-millis")]);
    }
    internal P.Capability Capability()=>P.Capability.Admit(Sources,Raw);
    internal M.Candidate Candidate()
    {var r=M.Calculate(Input);Assert.NotNull(r.Candidate);Assert.Null(r.Failure);return r.Candidate!;}
    internal Q.Result Calculate(P.Capability? p=null)=>Q.Calculate(Candidate(),Input,p??Capability(),Limits);
    internal void Npc32(int offset,uint value)=>Input=ManagedMembershipFixture.NpcImage(Input,x=>O.Put32(x,offset,value));
    internal static string Extra(string name)=>Cases.RootElement.GetProperty("extra").EnumerateArray().Single(x=>x.GetProperty("name").GetString()==name).GetProperty("body").GetString()!;
    internal static byte[] Capture(AionServerPacket packet)
    {
        var buffer=ByteBuffer.Allocate(AionServerPacket.MAX_USABLE_PACKET_BODY_SIZE+16).Order(ByteOrder.LITTLE_ENDIAN);packet.SetBuf(buffer);
        typeof(AionServerPacket).GetMethod("WriteImpl",BindingFlags.Instance|BindingFlags.NonPublic,new[]{typeof(AionConnection)})!.Invoke(packet,new object?[]{null});
        byte[] bytes=new byte[buffer.Position()];buffer.Flip();buffer.Get(bytes);return bytes;
    }
    internal static C.Catalog.Record[] Gear(string group="SWORD")
    {
        using var f=new StatSourceFixture();
        f.Xml("items/item_templates.xml",s=>
        {
            var root=XElement.Parse(s);foreach(int id in new[]{900000001,900000002,900000003})
                root.Add(new XElement("item_template",new XAttribute("id",id),new XAttribute("item_group",group)));
            return root.ToString();
        });
        var catalog=C.Read(f.Request(records:34,items:16));
        return [..new[]{900000001,900000002,900000003}.Select(id=>catalog.Retain(new(C.Authority.CSharp,C.Family.Item,id.ToString())))];
    }
    private static JsonDocument Unzip(ReadOnlySpan<byte> data)
    {using var input=new MemoryStream(Convert.FromBase64String(System.Text.Encoding.ASCII.GetString(data)));using var zip=new GZipStream(input,CompressionMode.Decompress);return JsonDocument.Parse(zip);}
    private static ReadOnlySpan<byte> SourcePayload => ""u8;
    private static ReadOnlySpan<byte> CasePayload => ""u8;
}
